export function getAddedEmployees(): Employee[] {
  try {
    const raw = localStorage.getItem('ardika_added_employees');
    if (raw) {
      return JSON.parse(raw);
    }
  } catch (e) {
    console.error(e);
  }
  return [];
}

export function getDeletedNips(): string[] {
  try {
    const raw = localStorage.getItem('ardika_deleted_nips');
    if (raw) return JSON.parse(raw);
  } catch (e) {
    console.error(e);
  }
  return [];
}

export function getAllEmployees(): Employee[] {
  const added = getAddedEmployees();
  const deletedNips = getDeletedNips();
  const combined = [...EMPLOYEES_DATA, ...added];
  return combined.filter((emp) => !deletedNips.includes(emp.nip));
}

export function findEmployeeByNip(nip: string): Employee | undefined {
  const cleanNip = nip.trim();
  const all = getAllEmployees();
  return all.find((e) => e.nip === cleanNip);
}

